/**
 * Client-side AI archers.
 *
 * The shot itself is generated by the shared AI model and resolved by the same
 * physics the player uses, so an AI arrow is a real arrow: it drifts in the
 * wind, it can line-cut, and it can miss. Difficulty only changes the skill
 * value, never the rules.
 */

import { generateShot, resolveShot } from '@shared/ai/archerAI';
import { getClassRules } from '@shared/rules/index';
import { clamp } from '@shared/math/random';
import type { BowClass, Difficulty, ScoredArrow, WindFieldConfig } from '@shared/types';
import type { ArcherProfile } from '../competition/types';

const NAMES: Array<{ name: string; country: string }> = [
  { name: 'A. Lindqvist', country: 'SWE' },
  { name: 'M. Rossi', country: 'ITA' },
  { name: 'K. Tanaka', country: 'JPN' },
  { name: 'L. Dubois', country: 'FRA' },
  { name: 'S. Okafor', country: 'GBR' },
  { name: 'J. Park', country: 'KOR' },
  { name: 'E. Novak', country: 'CZE' },
  { name: 'R. Silva', country: 'BRA' },
  { name: 'H. Weber', country: 'GER' },
  { name: 'N. Anders', country: 'DEN' },
  { name: 'T. Nguyen', country: 'USA' },
  { name: 'C. Meyer', country: 'SUI' },
];

const DIFFICULTY_SKILL: Record<Difficulty, number> = {
  arcade: 0.52,
  standard: 0.74,
  realistic: 0.84,
};

export class AIOpponent {
  readonly profile: ArcherProfile;
  readonly bowClass: BowClass;
  readonly distanceM: number;
  readonly wind: WindFieldConfig;
  readonly difficulty: Difficulty;
  private arrowIndex = 0;

  constructor(options: {
    bowClass: BowClass;
    distanceM: number;
    wind: WindFieldConfig;
    difficulty: Difficulty;
    seed?: number;
    name?: string;
    country?: string;
    skill?: number;
  }) {
    const seed = options.seed ?? 7;
    const picked = NAMES[seed % NAMES.length];
    this.bowClass = options.bowClass;
    this.distanceM = options.distanceM;
    this.wind = options.wind;
    this.difficulty = options.difficulty;
    this.profile = {
      id: `ai-${seed}`,
      name: options.name ?? picked.name,
      country: options.country ?? picked.country,
      skill: options.skill ?? DIFFICULTY_SKILL[options.difficulty],
      clutch: 0.4 + (seed % 5) * 0.1,
      style: seed % 3 === 0 ? 'fast' : seed % 3 === 1 ? 'steady' : 'streaky',
    };
  }

  /** One AI arrow, resolved through the shared physics. */
  shootArrow(pressure = 0): ScoredArrow {
    const index = this.arrowIndex++;
    const skill = clamp(this.profile.skill + (index % 7 === 0 ? -0.06 : 0) + (index % 11 === 0 ? 0.05 : 0), 0.1, 0.98);
    const req = generateShot(
      this.bowClass,
      {
        aim: { x: 0, y: 0 },
        consistency: clamp(skill * 0.9 + 0.1, 0.1, 0.96),
        clutch: this.profile.clutch,
      },
      { skill, wind: this.wind, pressure },
    );
    req.distanceM = this.distanceM;
    req.gear.drawWeightLb = getClassRules(this.bowClass).bow.drawWeightLb.default;
    const outcome = resolveShot(this.bowClass, req);
    return {
      ...outcome.score,
      index,
      impact: {
        x: outcome.faceImpact.x,
        y: outcome.faceImpact.y,
        speed: outcome.flight.impact.speed,
        angle: outcome.flight.impact.angle,
      },
    };
  }

  shootEnd(count: number, pressure = 0): ScoredArrow[] {
    const arrows: ScoredArrow[] = [];
    for (let i = 0; i < count; i++) arrows.push(this.shootArrow(pressure));
    return arrows;
  }

  reset(): void {
    this.arrowIndex = 0;
  }
}

/** A field of AI archers for the ranking round and the bracket. */
export function createField(count: number, bowClass: BowClass, difficulty: Difficulty, seed = 3): ArcherProfile[] {
  const field: ArcherProfile[] = [];
  for (let i = 0; i < count; i++) {
    const picked = NAMES[(seed + i * 5) % NAMES.length];
    const skill = clamp(DIFFICULTY_SKILL[difficulty] + ((i % 5) - 2) * 0.045, 0.35, 0.95);
    field.push({
      id: `ai-${i + 1}`,
      name: picked.name,
      country: picked.country,
      skill,
      clutch: 0.35 + ((i * 3) % 7) * 0.09,
      style: i % 3 === 0 ? 'fast' : i % 3 === 1 ? 'steady' : 'streaky',
    });
  }
  return field;
}
